"""Dedicated TrendForge paper-trading portfolio."""
from __future__ import annotations

import pandas as pd
import streamlit as st

from webapp.api_client import ApiError
from webapp.runtime import admin_key_configured, api_client
from webapp.ui import info_note, page_header, render_api_error


page_header(
    "Paper Trading Portfolio",
    "Separate simulated positions and P&L generated by the technical scanner. No broker orders are created from this portfolio.",
    kicker="Portfolio",
)

client = api_client(timeout=60)

try:
    payload = client.get_json("/workspace/paper-portfolio")
    readiness = client.get_json("/paper/readiness")
    auto = client.get_json("/paper/auto-entry/readiness")
    strategy_paper = client.get_json("/paper/strategy-driven/readiness")
    strategy_monitor = client.get_json("/paper/strategy-monitor/readiness")
    strategy_performance = client.get_json("/paper/strategy-performance")
    strategy_runtime = client.get_json(
        "/paper/strategy-runtime/reconciliation"
    )
    strategy_trades = client.get_json(
        "/paper/strategy-trades",
        params={"limit": 200},
    )
except ApiError as exc:
    render_api_error(exc, title="Paper portfolio unavailable")
    st.stop()

portfolio = payload.get("portfolio")
portfolio = portfolio if isinstance(portfolio, dict) else {}

m1, m2, m3, m4, m5, m6, m7 = st.columns(7)
with m1:
    st.metric("Open positions", int(portfolio.get("open_positions") or 0))
with m2:
    st.metric("Unrealized P&L", f"₹{float(portfolio.get('unrealized_pnl') or 0):,.2f}")
with m3:
    st.metric("Realized P&L", f"₹{float(portfolio.get('realized_pnl') or 0):,.2f}")
with m4:
    st.metric("Total P&L", f"₹{float(portfolio.get('total_pnl') or 0):,.2f}")
with m5:
    st.metric("Auto-entry", "ON" if auto.get("enabled") else "OFF")
with m6:
    st.metric(
        "Strategy paper",
        str(strategy_paper.get("status") or "unknown").upper(),
    )
with m7:
    st.metric(
        "Exit monitor",
        str(strategy_monitor.get("status") or "unknown").upper(),
    )

info_note(
    "Paper-only execution. Existing risk-per-trade, daily-loss, position-count, score/confidence and kill-switch controls remain authoritative."
)

st.subheader("R72.5.6 Restart-Safe Strategy Runtime")
r1, r2, r3, r4 = st.columns(4)
with r1:
    st.metric(
        "Runtime state",
        str(strategy_runtime.get("status") or "unknown").upper(),
    )
with r2:
    latest_scanner = strategy_runtime.get("latest_scanner")
    latest_scanner = (
        latest_scanner if isinstance(latest_scanner, dict) else {}
    )
    st.metric(
        "Scanner persisted",
        "YES" if latest_scanner.get("available") else "NO",
    )
with r3:
    latest_validation = strategy_runtime.get("latest_validation")
    latest_validation = (
        latest_validation
        if isinstance(latest_validation, dict)
        else {}
    )
    st.metric(
        "Validation persisted",
        "YES" if latest_validation.get("available") else "NO",
    )
with r4:
    st.metric(
        "Incomplete lineage",
        int(strategy_runtime.get("incomplete_lineage_positions") or 0),
    )

runtime_positions = strategy_runtime.get("positions")
runtime_positions = (
    runtime_positions if isinstance(runtime_positions, list) else []
)
if runtime_positions:
    with st.expander("Strategy lineage reconciliation", expanded=False):
        st.dataframe(
            pd.DataFrame(runtime_positions),
            use_container_width=True,
            hide_index=True,
        )
else:
    st.caption(
        "No open strategy paper position currently requires lineage reconciliation."
    )

positions = portfolio.get("positions")
positions = positions if isinstance(positions, list) else []
st.subheader("Open paper positions")
if positions:
    st.dataframe(
        pd.DataFrame(positions),
        use_container_width=True,
        hide_index=True,
    )
else:
    st.info("No open paper positions.")

st.subheader("Strategy-attributed open positions")
strategy_open = strategy_performance.get("open_strategy_positions")
strategy_open = strategy_open if isinstance(strategy_open, list) else []
if strategy_open:
    open_frame = pd.DataFrame(strategy_open)
    preferred_open = [
        "symbol",
        "strategy_name",
        "strategy_id",
        "trade_mode",
        "entry_price",
        "ltp",
        "quantity",
        "unrealized_pnl",
        "unrealized_pnl_pct",
        "source_scan_run_id",
        "validation_run_id",
    ]
    st.dataframe(
        open_frame[
            [
                column
                for column in preferred_open
                if column in open_frame.columns
            ]
        ],
        use_container_width=True,
        hide_index=True,
    )
else:
    st.info("No open strategy-attributed paper positions.")

st.subheader("Strategy performance attribution")
performance_rows = strategy_performance.get("rows")
performance_rows = (
    performance_rows
    if isinstance(performance_rows, list)
    else []
)
if performance_rows:
    perf_frame = pd.DataFrame(performance_rows)
    preferred_perf = [
        "strategy_name",
        "strategy_id",
        "trade_mode",
        "closed_trades",
        "wins",
        "losses",
        "win_rate_pct",
        "net_pnl",
        "average_pnl",
        "return_on_entry_notional_pct",
        "last_exit_at",
    ]
    st.dataframe(
        perf_frame[
            [
                column
                for column in preferred_perf
                if column in perf_frame.columns
            ]
        ],
        use_container_width=True,
        hide_index=True,
    )
else:
    st.info(
        "No closed strategy-attributed paper trades are available yet."
    )

recent_strategy_rows = strategy_trades.get("rows")
recent_strategy_rows = (
    recent_strategy_rows
    if isinstance(recent_strategy_rows, list)
    else []
)
with st.expander("Recent strategy-attributed paper trades", expanded=False):
    if recent_strategy_rows:
        st.dataframe(
            pd.DataFrame(recent_strategy_rows),
            use_container_width=True,
            hide_index=True,
        )
    else:
        st.caption("No strategy-attributed paper trades recorded yet.")

st.subheader("Closed paper trades")
closed = payload.get("closed_trades")
closed = closed if isinstance(closed, list) else []
if closed:
    st.dataframe(
        pd.DataFrame(closed),
        use_container_width=True,
        hide_index=True,
    )
else:
    st.info("No closed paper trades.")

st.divider()
c1, c2, c3 = st.columns(3)
with c1:
    st.metric("Paper runtime", str(readiness.get("status") or "unknown").upper())
with c2:
    st.metric("Kill switch", "ON" if readiness.get("kill_switch") else "OFF")
with c3:
    monitor = readiness.get("automatic_monitor")
    monitor = monitor if isinstance(monitor, dict) else {}
    st.metric("Quote monitor", str(monitor.get("status") or "unknown").upper())

if admin_key_configured():
    st.subheader("Strategy exit monitoring")
    strategy_enabled = bool(strategy_monitor.get("enabled"))
    st.caption(
        "Automatic strategy-exit checks are "
        + ("enabled." if strategy_enabled else "disabled by environment. ")
        + "The manual check below is admin-gated and evaluates completed candles only."
    )
    if st.button(
        "Run Strategy Exit Check",
        use_container_width=True,
        key="tf_r7255_strategy_exit_tick",
    ):
        try:
            exit_result = client.post_json(
                "/paper/strategy-monitor/tick",
                {},
                timeout=120,
            )
            st.session_state["tf_r7255_exit_result"] = exit_result
            if exit_result.get("closed"):
                st.success(
                    f"Closed {len(exit_result.get('closed') or [])} paper "
                    "position(s) on strategy exit signal."
                )
            else:
                st.info(
                    "Strategy exit check completed; no strategy exit was executed."
                )
        except ApiError as exc:
            render_api_error(
                exc,
                title="Strategy exit check failed",
            )

    latest_exit_result = st.session_state.get("tf_r7255_exit_result")
    if isinstance(latest_exit_result, dict):
        with st.expander(
            "Latest strategy exit evidence",
            expanded=False,
        ):
            st.json(latest_exit_result)

    k1, k2 = st.columns(2)
    with k1:
        if st.button("Enable paper kill switch", use_container_width=True):
            try:
                client.post_json("/paper/kill-switch", {"enabled": True})
                st.rerun()
            except ApiError as exc:
                render_api_error(exc)
    with k2:
        if st.button("Disable paper kill switch", use_container_width=True):
            try:
                client.post_json("/paper/kill-switch", {"enabled": False})
                st.rerun()
            except ApiError as exc:
                render_api_error(exc)
